var THEMES = [
{ id: 'paper', name: 'נייר', hint: 'בהיר ונייטרלי' },
{ id: 'graphite', name: 'גרפיט', hint: 'כהה וכחלחל' },
{ id: 'sand', name: 'חול', hint: 'בהיר וחמים' },
{ id: 'ink', name: 'דיו', hint: 'כהה וכחול עמוק' }
];
function themeId() {
var v = null;
try { v = localStorage.getItem('madaf_theme'); } catch (e) {}
for (var i = 0; i < THEMES.length; i++) if (THEMES[i].id === v) return v;
return 'paper';
}
function density() {
var v = null;
try { v = localStorage.getItem('madaf_density'); } catch (e) {}
return v === 'full' ? 'full' : 'compact';
}
function setDensity(v) {
try { localStorage.setItem('madaf_density', v); } catch (e) {}
applyTheme();
}
function applyTheme(id) {
var t = id || themeId(), cls = [];
if (t !== 'paper') cls.push('t-' + t);
if (density() === 'full') cls.push('d-full');
root.className = cls.join(' ');
}
function setTheme(id) {
try { localStorage.setItem('madaf_theme', id); } catch (e) {}
applyTheme(id);
}
