function nFiles(n) { return n === 1 ? 'קובץ אחד' : n + ' קבצים'; }
function nCourses(n) { return n === 1 ? 'קורס אחד' : n + ' קורסים'; }
function nRec(n) { return n === 1 ? 'הקלטה אחת' : n + ' הקלטות'; }
function nMeet(n) { return n === 1 ? 'מפגש אחד' : n + ' מפגשים'; }
