var LECT_TITLE = /^(פרופ|ד"ר|דר|עו"ד|מר|גב|רו"ח|אדר|אלוף|תא"ל|השופט|השופטת)['׳"()\s]*/;
function lnorm(t) {
return String(t || '').replace(/["'׳\-]/g, ' ').replace(/\s+/g, ' ').trim();
}
function lecturerFor(courseFull) {
var c = lnorm(courseFull), cw = c.split(' '), best = null, bestN = 0;
for (var i = 0; i < LECT.length; i++) {
var nm = lnorm(LECT[i][0].replace(LECT_TITLE, ''));
var w = nm.split(' ').filter(function (q) { return q.length > 1; });
if (w.length < 2) continue;
var ok = w.every(function (q) {
if (c.indexOf(q) > -1) return true;
return cw.some(function (pp) {
return pp.length > 3 && q.length > 3 && pp.slice(0, 4) === q.slice(0, 4) &&
Math.abs(pp.length - q.length) < 3;
});
});
if (ok && w.length > bestN) { best = LECT[i]; bestN = w.length; }
}
return best ? { name: best[0], url: 'https://www.colman.ac.il/teaching/lecturers/' + best[1] + '/', mail: best[2] } : null;
}
